-- Iterate with index tracking
local function forEach(t, fn)
  for i, v in ipairs(t) do
    fn(i, v)
  end
end

-- Move elements
local src = {1, 2, 3, 4, 5}
local dest = {}
table.move(src, 2, 4, 1, dest)  -- move src[2:4] to dest[1:3]
-- dest = {2, 3, 4}

